CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE `games` (`name` TEXT NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, `soundToggleType` INTEGER NOT NULL DEFAULT 0, `configType` INTEGER, `useWideViewPortAndOverviewMode` INTEGER, `leaderboardId` TEXT, `section` TEXT, `has_rewarded_video` INTEGER, `each_n_seconds` INTEGER, `each_n_levels` INTEGER, `each_n_scores` INTEGER, `minimum_level` INTEGER, `minimum_time_played_in_game_sec` INTEGER, `gameFinishedAd` INTEGER, `js_popup_each_n_seconds` INTEGER, `remote_image_url` TEXT, `remote_url_version` INTEGER, `remote_url` TEXT, `size_mb` REAL, `title` TEXT, `category` TEXT, `isHorizontal` INTEGER, PRIMARY KEY(`name`));
CREATE TABLE `banners` (`gameId` TEXT NOT NULL, `position` INTEGER NOT NULL DEFAULT 0, `image_url` TEXT NOT NULL, PRIMARY KEY(`gameId`));
CREATE TABLE `debug_hardcoded_games` (`name` TEXT NOT NULL, `isHorizontal` INTEGER NOT NULL, `has_rewarded_video` INTEGER NOT NULL, `each_n_seconds` INTEGER, `each_n_levels` INTEGER, `each_n_scores` INTEGER, `minimum_level` INTEGER NOT NULL, `minimum_time_played_in_game_sec` INTEGER NOT NULL, `gameFinishedAd` INTEGER NOT NULL, `js_popup_each_n_seconds` INTEGER, PRIMARY KEY(`name`));
CREATE TABLE `offline_games_interstitial` (`version` INTEGER NOT NULL, `url` TEXT NOT NULL, `actionUrl` TEXT NOT NULL, `showDailyLimit` INTEGER NOT NULL, PRIMARY KEY(`version`));
CREATE TABLE `google_play_app_banners` (`id` INTEGER NOT NULL, `packageName` TEXT NOT NULL, `referrer` TEXT NOT NULL, `showTimes` INTEGER NOT NULL, `minTimesToOpenMenuBeforeShow` INTEGER NOT NULL, `showEachMenuOpen` INTEGER NOT NULL, `title` TEXT NOT NULL, `subtitle` TEXT NOT NULL, `iconUrl` TEXT NOT NULL, `buttonText` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
